SELECT
FROM product_unit pu INNER JOIN product p ON p.product_id = pu.product_id INNER JOIN unit u ON u.unit_id = pu.unit_id WHERE p.company_id = #{companyId} AND pu.product_id = #{productId}
AND pu.use_yn = #{useYn}
ORDER BY pu.use_yn DESC, CASE WHEN pu.is_base_yn = 'Y' THEN 0 ELSE 1 END, u.unit_name ASC, pu.product_unit_id ASC

SELECT

FROM product_unit pu
INNER JOIN product p
ON p.product_id = pu.product_id
INNER JOIN unit u
ON u.unit_id = pu.unit_id
WHERE p.company_id = #{companyId}
AND pu.product_id = #{productId}
AND pu.product_unit_id = #{productUnitId}

