mapper.update:
UPDATE product_unit
SET unit_id = #{productUnit.unitId},
conversion_qty =
#{productUnit.conversionQty},
is_base_yn =
#{productUnit.isBaseYn},
updated_at = CAST(
SYSTIMESTAMP AT TIME ZONE 'Asia/Seoul'
AS TIMESTAMP
),
updated_by =
#{productUnit.updatedBy}
WHERE product_unit_id =
#{productUnit.productUnitId}
AND product_id =
#{productUnit.productId}
AND EXISTS (
SELECT 1
FROM product p
WHERE p.product_id =
#{productUnit.productId}
AND p.company_id = #{companyId}
)

UPDATE product_unit
SET use_yn = #{useYn},
is_base_yn = CASE
WHEN #{useYn} = 'N' THEN 'N'
ELSE is_base_yn
END,
updated_at = CAST(
SYSTIMESTAMP AT TIME ZONE 'Asia/Seoul'
AS TIMESTAMP
),
updated_by = #{updatedBy}
WHERE product_unit_id = #{productUnitId}
AND product_id = #{productId}
AND EXISTS (
SELECT 1
FROM product p
WHERE p.product_id = #{productId}
AND p.company_id = #{companyId}
)
